import math

def build_agent(sandbox):
    return None

def agent_action(sandbox, agent_body, step_count):
    pos = sandbox.get_agent_position()
    vel = sandbox.get_agent_velocity()
    next_sw = sandbox.get_next_required_switch()

    if next_sw is None:
        return

    # Track steps since each switch was triggered
    A_triggered_step = None
    B_triggered_step = None
    C_triggered_step = None

    target_zone = next_sw

    # Determine if agent is in the target zone
    in_target = False
    if target_zone == 'A':
        in_target = (1.5 <= pos[0] <= 2.5) and (1.5 <= pos[1] <= 2.5)
    elif target_zone == 'B':
        in_target = (4.25 <= pos[0] <= 5.65) and (2.8 <= pos[1] <= 3.6)
    elif target_zone == 'C':
        in_target = (7.5 <= pos[0] <= 8.5) and (1.5 <= pos[1] <= 2.5)

    if not in_target:
        # Move towards target zone
        if target_zone == 'A':
            target = (2.0, 2.0)
        elif target_zone == 'B':
            target = (4.95, 3.2)
        elif target_zone == 'C':
            target = (8.0, 2.0)

        dx = target[0] - pos[0]
        dy = target[1] - pos[1]
        distance = math.hypot(dx, dy)

        if distance > 0:
            dx_norm = dx / distance
            dy_norm = dy / distance
            force_x, force_y = calculate_force(dx_norm, dy_norm)
            sandbox.apply_agent_force(force_x, force_y)

    if in_target:
        steps_in_current = sandbox.get_steps_in_current_zone()
        if steps_in_current >= 25:
            # Trigger the switch
            sandbox.get_triggered_switches()

            if target_zone == 'A':
                A_triggered_step = step_count
                # Check barrier delay
                barrier_delay = sandbox.get_barrier_delay_steps()
                if barrier_delay > 0:
                    return
                # Move to B
                target_zone = 'B'
            elif target_zone == 'B':
                if A_triggered_step is not None and step_count - A_triggered_step <= 160:
                    B_triggered_step = step_count
                    # Check cooldown
                    cooldown = sandbox.get_cooldown_remaining()
                    if cooldown > 0:
                        return
                    # Move to C
                    target_zone = 'C'
                else:
                    return
            elif target_zone == 'C':
                if B_triggered_step is not None and step_count - B_triggered_step <= 400:
                    y = pos[1]
                    if y >= 2.9:
                        C_triggered_step = step_count
                else:
                    return
        else:
            # Apply force to stay in zone
            force_x = -vel[0] * 100
            force_y = -vel[1] * 100
            sandbox.apply_agent_force(force_x, force_y)

    # Ensure speed constraint
    if in_target:
        current_speed = math.hypot(vel[0], vel[1])
        if current_speed > 0.5:
            force_x = -vel[0] * 100
            force_y = -vel[1] * 100
            sandbox.apply_agent_force(force_x, force_y)

    # Check if sequence is complete
    if next_sw is None:
        return

def calculate_force(direction_x, direction_y):
    length = math.hypot(direction_x, direction_y)
    if length == 0:
        return (0, 0)
    ux = direction_x / length
    uy = direction_y / length
    force_x = 60 * ux
    force_y = 60 * uy
    force_x = min(force_x, 50)
    force_y = min(force_y, 50)
    return (force_x, force_y)
